F2 = [['新建 3 个 Pod', '189 / 190 / 191'], ['每个 IP 一个文件', '记录沙箱 ID'], ['last_reserved_ip.0', '191'], ['删除 b', '2.2 秒后文件才删'], ['新建 d', '192(不回头)']]
